import type { CircuitLayout } from "../../shared/api/types";
import { openExternalUrl } from "../../shared/platform/tauriBridge";

/** Track drawing generated by the backend from GeoJSON; stroke follows the theme color. */
export function CircuitMap({ circuitLayout, circuitName }: { circuitLayout: CircuitLayout; circuitName: string }) {
  return (
    <figure className="circuit-map">
      <svg viewBox={circuitLayout.svgViewBox} role="img" aria-label={circuitName}>
        <path className="circuit-map__outline" d={circuitLayout.svgPath} />
        <path className="circuit-map__track" d={circuitLayout.svgPath} />
      </svg>
      <figcaption>
        <button type="button" className="link-button" onClick={() => openExternalUrl(circuitLayout.attributionUrl)}>
          {circuitLayout.attributionText}
        </button>
      </figcaption>
    </figure>
  );
}
